CREATE OR REPLACE FUNCTION public.recon_create(p_question text, p_title text, p_target_ref text, p_target_type text, p_max_steps integer, p_payload jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path = public AS $$ DECLARE result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF length(p_question) < 5 OR length(p_question) > 500 OR p_max_steps < 3 OR p_max_steps > 20 THEN RAISE EXCEPTION 'Invalid investigation input'; END IF; INSERT INTO public.investigations(user_id,question,title,target_ref,target_type,max_steps,status) VALUES(auth.uid(),p_question,p_title,p_target_ref,p_target_type,p_max_steps,'queued') RETURNING id INTO result; INSERT INTO public.repo_indexes(investigation_id,user_id,files) VALUES(result,auth.uid(),p_payload); RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.recon_create(text,text,text,text,integer,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.recon_create(text,text,text,text,integer,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.recon_set_retention(p_days integer) RETURNS void LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF p_days IS NOT NULL AND p_days NOT IN (7,30,90) THEN RAISE EXCEPTION 'Invalid retention duration'; END IF; INSERT INTO public.recon_preferences(user_id,retention_days,updated_at) VALUES(auth.uid(),p_days,now()) ON CONFLICT(user_id) DO UPDATE SET retention_days = EXCLUDED.retention_days, updated_at = now(); UPDATE public.investigations SET expires_at = CASE WHEN p_days IS NULL THEN NULL ELSE created_at + make_interval(days => p_days) END WHERE user_id = auth.uid(); END; $$;
REVOKE ALL ON FUNCTION public.recon_set_retention(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.recon_set_retention(integer) TO authenticated;